print(">> ZEVORIX LINK: 'تحليل ذكي' button added." if not _ZL_WARNINGS else ">> ZEVORIX LINK: اكتمل مع تحذيرات؛ راجعها.")


ICON_SIZES = {"mdpi":48,"hdpi":72,"xhdpi":96,"xxhdpi":144,"xxxhdpi":192}
LAUNCHER_NAMES = ("ic_launcher", "ic_launcher_round")

def main():
    root = Path(sys.argv[1] if len(sys.argv) > 1 else "Gradiometer")
    for rel, content in FILES.items():
        path = root / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8", newline="\n")
        print("created:", path)

    # Keep Firebase Hosting copies identical to the root templates on every generation.
    public = root / "public"
    public.mkdir(parents=True, exist_ok=True)
    for name in ("account-deletion.html", "privacy-policy.html"):
        source = root / name
        if source.exists():
            (public / name).write_text(source.read_text(encoding="utf-8"), encoding="utf-8", newline="\n")

    # Validate static-only localization keys during generation.
    validator = root / "scripts" / "validate_i18n.py"
    if validator.exists():
        subprocess.run([sys.executable, str(validator)], check=True)

    try:
        from PIL import Image, ImageDraw
        im = Image.new("RGB", (512, 512), (15, 28, 48))
        draw = ImageDraw.Draw(im)
        draw.rounded_rectangle((55,55,457,457), radius=90, outline=(60,210,190), width=18)
        draw.line((125,340,205,170,280,300,375,125), fill=(245,190,75), width=25)
        for density, px in ICON_SIZES.items():
            folder = root / "app" / "src" / "main" / "res" / ("mipmap-" + density)
            folder.mkdir(parents=True, exist_ok=True)
            resized = im.resize((px,px), Image.Resampling.LANCZOS)
            for name in LAUNCHER_NAMES:
                resized.save(folder / (name + ".png"))
    except ImportError:
        print("ERROR: Pillow required to generate temporary launcher icon. Run pip install Pillow.")
        sys.exit(1)

    print("\nProject generated. Add Gradiometer google-services.json and release signing secrets before release build.")

# ==============================================================================
# FIX: LanguageScreen.kt يستخدم R.string.account_uid دون استيراد R
#      => "Unresolved reference 'R'". الإصلاح آمن ويمكن تشغيله أكثر من مرة (لا يكرر الاستيراد).
# ==============================================================================
def _fix_language_screen_r_import():
    key = "app/src/main/java/io/mycompany/gradiometer/i18n/LanguageScreen.kt"
    imp = "import io.mycompany.gradiometer.R"
    if key not in FILES:
        print(">> [WARNING] R import fix: الملف غير موجود " + key)
        return
    text = FILES[key]
    if any(line.strip() == imp for line in text.splitlines()):
        return  # الاستيراد موجود مسبقاً: لا تكرار
    anchor = "import androidx.compose.ui.res.stringResource\n"
    if text.count(anchor) == 1:
        FILES[key] = text.replace(anchor, anchor + imp + "\n", 1)
        return
    # احتياطي: إن لم يوجد السطر المرجعي نضيف الاستيراد بعد سطر package
    pkg = "package io.mycompany.gradiometer.i18n\n"
    if text.count(pkg) == 1:
        FILES[key] = text.replace(pkg, pkg + "\n" + imp + "\n", 1)
        return
    print(">> [WARNING] R import fix: لم يُعثر على موضع مناسب للاستيراد")


_fix_language_screen_r_import()


if __name__ == "__main__":
    main()
